before.content:
assert.doesNotMatch(stage6Ubuntu, /server_rss=\$\(\(server_rss \+ memory_current\)\)/);
assert.match(stage6Ubuntu, /memory\.events/);
assert.match(stage6Ubuntu, /memory\.swap\.current/);
assert.match(stage6Ubuntu, /STAGE6_PERFORMANCE_OK/);
assert.match(stage6Ubuntu, /docker image save/);
assert.doesNotMatch(stage6Ubuntu, /docker export/);

after.content:
assert.match(stage6Ubuntu, /performance-cold\.stdout/);
assert.match(stage6Ubuntu, /cold_exit_code/);
assert.match(stage6Performance, /hostColdReadySampleMillis/);
const coldClientIndex = stage6Performance.indexOf("HttpClient probeClient = HttpClient.newHttpClient()");
const coldLoopIndex = stage6Performance.indexOf("for (int sample = 0; sample < COLD_SAMPLES; sample++)");
assert.ok(coldClientIndex >= 0 && coldClientIndex < coldLoopIndex);
assert.match(stage6Performance, /probeClient\.send\(/);
assert.doesNotMatch(stage6Performance, /HttpClient\.newHttpClient\(\)\.send\(/);
assert.match(stage6Ubuntu, /--network ji-stage6-performance-network --cpus 2 --memory 4g --memory-swap 4g/);
assert.match(stage6Ubuntu, /\/opt\/ji-host\/runtime\/bin\/java -cp '\/opt\/ji-stage6\/\*:\/opt\/ji-host\/lib\/\*'/);
assert.match(stage6Ubuntu, /JI_STAGE6_PERFORMANCE_HOLD_FILE=\/data\/hold-performance/);
